-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + H", hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + L", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + K", hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + J", hl.dsp.focus({ direction = "down" }))

hl.bind(mainMod .. " + SHIFT + H", hl.dsp.window.move({ direction = "l" }))
hl.bind(mainMod .. " + SHIFT + L", hl.dsp.window.move({ direction = "r" }))
hl.bind(mainMod .. " + SHIFT + K", hl.dsp.window.move({ direction = "u" }))
hl.bind(mainMod .. " + SHIFT + J", hl.dsp.window.move({ direction = "d" }))

hl.bind(mainMod .. " + E", hl.dsp.layout("orientationnext"))

hl.bind("ALT + R", hl.dsp.submap("resize"))
-- will start a submap called "resize"
hl.define_submap("resize", function()
    hl.bind("l", hl.dsp.window.resize({ x = 50, y = 0, relative = true }))
    hl.bind("h", hl.dsp.window.resize({ x = -50, y = 0, relative = true }))
    hl.bind("k", hl.dsp.window.resize({ x = 0, y = -50, relative = true }))
    hl.bind("j", hl.dsp.window.resize({ x = 0, y = 50, relative = true }))
    -- use reset to go back to the global submap
    hl.bind("escape", hl.dsp.submap("reset"))
    -- will reset the submap, meaning end the current one and return to the global one
end)

hl.bind(altMod .. " + l", hl.dsp.window.resize({ x = 50, y = 0, relative = true }))
hl.bind(altMod .. " + h", hl.dsp.window.resize({ x = -50, y = 0, relative = true }))
hl.bind(altMod .. " + k", hl.dsp.window.resize({ x = 0, y = -50, relative = true }))
hl.bind(altMod .. " + j", hl.dsp.window.resize({ x = 0, y = 50, relative = true }))

